mapper.select:
SELECT d.id, d.name, d.category_id, d.price, d.image, d.description, d.status, d.stock, d.tags, d.art FROM dish d LEFT JOIN category c ON c.id = d.category_id
AND d.name LIKE #{namePattern} ESCAPE '!'
AND d.category_id = #{query.categoryId}
AND d.status = #{query.status}
ORDER BY c.sort ASC, c.id ASC, d.id ASC
